<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api,apiRuntime}from'../../api/client';import{toOrderProjection,type ProjectProjection}from'../../api/project-contract';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import{getOrCreateCommand}from'../../domain/command-identity';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),core=ref<ProjectProjection|null>(null),orderRef=ref(''),error=ref(''),loading=ref(false);const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const canConfirmPayment=computed(()=>ready.value&&!!core.value?.allowedActions.some(a=>a.actionCode==='REQUEST_MOCK_PAYMENT'))
async function refresh(){if(!orderRef.value)return;try{if(apiRuntime.mode==='PROJECT_MOCK_API'){core.value=await api.getCoreProjection(orderRef.value);p.value=toOrderProjection(core.value)}else p.value=await api.getProjection(orderRef.value)}catch{error.value='读取失败，只能只读重试。'}}
async function confirmPayment(){if(!ready.value||!core.value)return;loading.value=true;try{const c=getOrCreateCommand(uni,`mock-payment:${orderRef.value}`);core.value=await api.confirmMockPayment(orderRef.value,c.commandId,c.idempotencyKey,core.value.projectionVersion,core.value.aggregateVersion);uni.setStorageSync(`coreProjection:${orderRef.value}`,core.value);uni.navigateTo({url:`/pages/order/progress?orderRef=${encodeURIComponent(orderRef.value)}`})}catch{error.value='Mock支付结果未确认；保留原命令身份。'}finally{loading.value=false}}
onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})
</script>
<template><view class="page"><AppHeader left="← 订单" @left="uni.navigateBack()"/><view class="content"><view class="heading" role="heading" aria-level="1">正在确认支付结果</view><StatusNotice v-if="error" tone="risk" title="读取错误">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="risk" title="STALE / 冻结快照不一致">后续业务动作资格为 0。</StatusNotice><view class="card"><view class="kv"><text>订单引用</text><text>{{orderRef||'UNKNOWN'}}</text></view><view class="kv"><text>投影/聚合版本</text><text>{{core?.projectionVersion??'—'}} / {{core?.aggregateVersion??'—'}}</text></view></view></view><view class="action"><button v-if="apiRuntime.mode==='PROJECT_MOCK_API'" class="primary" :disabled="!ready||!core||loading" @click="confirmPayment">确认 Mock 支付</button><button v-else class="primary" @click="refresh">只读查询</button></view></view></template><style src="../../styles/shared.css"></style>
